BEGIN;
CREATE OR REPLACE FUNCTION termination_reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'strategy termination history is immutable'; END $$;
CREATE TABLE IF NOT EXISTS termination_scopes (scope_hash text PRIMARY KEY CHECK(scope_hash ~ '^[a-f0-9]{64}$'), operator_test_id text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS termination_requests (scope_hash text NOT NULL REFERENCES termination_scopes(scope_hash), request_hash text PRIMARY KEY CHECK(request_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS termination_latches (scope_hash text NOT NULL REFERENCES termination_scopes(scope_hash), latch_hash text PRIMARY KEY CHECK(latch_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS termination_dependency_bindings (scope_hash text NOT NULL REFERENCES termination_scopes(scope_hash), binding_hash text PRIMARY KEY CHECK(binding_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS termination_context_bindings (scope_hash text NOT NULL REFERENCES termination_scopes(scope_hash), binding_hash text PRIMARY KEY CHECK(binding_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS termination_manifests (scope_hash text NOT NULL REFERENCES termination_scopes(scope_hash), manifest_hash text PRIMARY KEY CHECK(manifest_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS termination_observations (scope_hash text NOT NULL REFERENCES termination_scopes(scope_hash), observation_hash text PRIMARY KEY CHECK(observation_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS termination_inventory_items (scope_hash text NOT NULL REFERENCES termination_scopes(scope_hash), item_hash text PRIMARY KEY CHECK(item_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS termination_snapshots (scope_hash text NOT NULL REFERENCES termination_scopes(scope_hash), snapshot_hash text PRIMARY KEY CHECK(snapshot_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS termination_plans (scope_hash text NOT NULL REFERENCES termination_scopes(scope_hash), plan_hash text PRIMARY KEY CHECK(plan_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS termination_steps (scope_hash text NOT NULL REFERENCES termination_scopes(scope_hash), step_hash text PRIMARY KEY CHECK(step_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS termination_attempts (scope_hash text NOT NULL REFERENCES termination_scopes(scope_hash), attempt_hash text PRIMARY KEY CHECK(attempt_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS termination_step_receipts (scope_hash text NOT NULL REFERENCES termination_scopes(scope_hash), receipt_hash text PRIMARY KEY CHECK(receipt_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS termination_checkpoints (scope_hash text NOT NULL REFERENCES termination_scopes(scope_hash), checkpoint_hash text PRIMARY KEY CHECK(checkpoint_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS termination_residuals (scope_hash text NOT NULL REFERENCES termination_scopes(scope_hash), residual_hash text PRIMARY KEY CHECK(residual_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS termination_decisions (scope_hash text NOT NULL REFERENCES termination_scopes(scope_hash), decision_hash text PRIMARY KEY CHECK(decision_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS termination_completions (scope_hash text NOT NULL REFERENCES termination_scopes(scope_hash), completion_hash text PRIMARY KEY CHECK(completion_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS termination_workflow_events (scope_hash text NOT NULL REFERENCES termination_scopes(scope_hash), event_hash text PRIMARY KEY CHECK(event_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS termination_conflicts (scope_hash text NOT NULL REFERENCES termination_scopes(scope_hash), conflict_hash text PRIMARY KEY CHECK(conflict_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS termination_request_claims (operator_test_id text NOT NULL, scope_hash text NOT NULL REFERENCES termination_scopes(scope_hash), idempotency_key text NOT NULL, request_hash text NOT NULL CHECK(request_hash ~ '^[a-f0-9]{64}$') REFERENCES termination_requests(request_hash), test_request_hash text NOT NULL CHECK(test_request_hash ~ '^[a-f0-9]{64}$'), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(operator_test_id,scope_hash,idempotency_key));
ALTER TABLE termination_request_claims ADD COLUMN IF NOT EXISTS test_request_hash text;
CREATE TABLE IF NOT EXISTS termination_test_center_bundles (run_id text PRIMARY KEY REFERENCES agent_test_center_runs(run_id), scope_hash text NOT NULL REFERENCES termination_scopes(scope_hash), decision_hash text NOT NULL REFERENCES termination_decisions(decision_hash), created_at timestamptz NOT NULL DEFAULT now());
DO $$ DECLARE item text; BEGIN FOREACH item IN ARRAY ARRAY['termination_scopes','termination_requests','termination_latches','termination_dependency_bindings','termination_context_bindings','termination_manifests','termination_observations','termination_inventory_items','termination_snapshots','termination_plans','termination_steps','termination_attempts','termination_step_receipts','termination_checkpoints','termination_residuals','termination_decisions','termination_completions','termination_workflow_events','termination_conflicts','termination_request_claims','termination_test_center_bundles'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS %I_immutable ON %I', item,item); EXECUTE format('CREATE TRIGGER %I_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION termination_reject_mutation()', item,item); END LOOP; END $$;
COMMIT;
